create extension if not exists pgcrypto;
create table if not exists public.events (id uuid primary key default gen_random_uuid(), owner_id uuid not null references auth.users(id) on delete cascade, revision integer not null default 1 check (revision > 0), title text not null, description text not null default '', location text not null default '', starts_at timestamptz not null, ends_at timestamptz not null, timezone text not null, links jsonb not null default '[]'::jsonb, organizer_contact text not null default '', status text not null default 'draft' check (status in ('draft','preparing','ready','published','changed','failed')), created_at timestamptz not null default now(), updated_at timestamptz not null default now(), check (ends_at > starts_at));
create table if not exists public.invitees (id uuid primary key default gen_random_uuid(), event_id uuid not null references public.events(id) on delete cascade, email text not null, display_name text, created_at timestamptz not null default now(), unique(event_id, email));
create table if not exists public.inclusion_facts (event_id uuid not null references public.events(id) on delete cascade, revision integer not null, step_free text not null default 'unknown' check (step_free in ('yes','no','unknown')), elevator text not null default 'unknown' check (elevator in ('yes','no','unknown')), captions text not null default 'unknown' check (captions in ('yes','no','unknown')), diet_options text not null default 'unknown', loud_sound_strobes text not null default 'unknown', observance_notes text not null default '', source text, confirmed_by text, confirmed_at timestamptz, primary key(event_id, revision));
create table if not exists public.generated_content (id uuid primary key default gen_random_uuid(), event_id uuid not null references public.events(id) on delete cascade, event_revision integer not null, kind text not null, body text not null, producer text not null, state text not null default 'queued', created_at timestamptz not null default now());
create table if not exists public.operations (id uuid primary key default gen_random_uuid(), event_id uuid not null references public.events(id) on delete cascade, event_revision integer not null, kind text not null, idempotency_key text not null unique, authorization_reference text, state text not null default 'queued', attempts integer not null default 0, error_code text, provider_receipt jsonb, created_at timestamptz not null default now(), updated_at timestamptz not null default now());
create table if not exists public.rsvps (id uuid primary key default gen_random_uuid(), event_id uuid not null references public.events(id) on delete cascade, invitee_id uuid not null references public.invitees(id) on delete cascade, status text not null default 'no_response', source text not null, source_message_id text, observed_at timestamptz not null default now(), event_revision integer not null, unique(event_id, invitee_id, source_message_id));
create table if not exists public.artifacts (id uuid primary key default gen_random_uuid(), event_id uuid not null references public.events(id) on delete cascade, event_revision integer not null, kind text not null, storage_path text, provider_design_id text, exported_version_id text, content_hash text, current_url text, access_policy text not null default 'private', created_at timestamptz not null default now());
alter table public.events enable row level security; alter table public.invitees enable row level security; alter table public.inclusion_facts enable row level security; alter table public.generated_content enable row level security; alter table public.operations enable row level security; alter table public.rsvps enable row level security; alter table public.artifacts enable row level security;
do $$ begin create policy "owners manage events" on public.events for all using (auth.uid() = owner_id) with check (auth.uid() = owner_id); exception when duplicate_object then null; end $$;
do $$ begin create policy "owners manage invitees" on public.invitees for all using (exists (select 1 from public.events e where e.id = event_id and e.owner_id = auth.uid())) with check (exists (select 1 from public.events e where e.id = event_id and e.owner_id = auth.uid())); exception when duplicate_object then null; end $$;
do $$ begin create policy "owners manage inclusion" on public.inclusion_facts for all using (exists (select 1 from public.events e where e.id = event_id and e.owner_id = auth.uid())) with check (exists (select 1 from public.events e where e.id = event_id and e.owner_id = auth.uid())); exception when duplicate_object then null; end $$;
do $$ begin create policy "owners manage content" on public.generated_content for all using (exists (select 1 from public.events e where e.id = event_id and e.owner_id = auth.uid())) with check (exists (select 1 from public.events e where e.id = event_id and e.owner_id = auth.uid())); exception when duplicate_object then null; end $$;
do $$ begin create policy "owners manage operations" on public.operations for all using (exists (select 1 from public.events e where e.id = event_id and e.owner_id = auth.uid())) with check (exists (select 1 from public.events e where e.id = event_id and e.owner_id = auth.uid())); exception when duplicate_object then null; end $$;
do $$ begin create policy "owners manage rsvps" on public.rsvps for all using (exists (select 1 from public.events e where e.id = event_id and e.owner_id = auth.uid())) with check (exists (select 1 from public.events e where e.id = event_id and e.owner_id = auth.uid())); exception when duplicate_object then null; end $$;
do $$ begin create policy "owners manage artifacts" on public.artifacts for all using (exists (select 1 from public.events e where e.id = event_id and e.owner_id = auth.uid())) with check (exists (select 1 from public.events e where e.id = event_id and e.owner_id = auth.uid())); exception when duplicate_object then null; end $$;
